    "question": "統計学に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 一般に、母集団の大きさをN、標本の大きさをnとした場合、この母集団から同等な確率で取り出される標本の数は、復元抽出ではNCₙ通り、非復元抽出ではN × N × … × N = Nⁿ通りある。また、母集団の大きさが非常に大きい場合は、復元抽出と非復元抽出により抽出した標本に差が生じてしまうため注意が必要である。\nB. 中心極限定理とは、ある母集団から抽出された大きさnの標本の標本平均について、nが十分に大きければ、標本平均の確率分布は正規分布に近似するという定理である。中心極限定理は、平均と分散を持つ母集団において、母集団の確率分布に関係なく成り立つという特徴がある。\nC. データのばらつき度合いを数値で表したものを散布度といい、偏差や標準偏差などがある。偏差は、n個のデータの平均値をx̄としたときの、各データxᵢとx̄の差を2乗した値であり、標準偏差は、偏差をnで割った値である。\nD. 帰無仮説の下での棄却域は、対立仮説との関係で、左側、中央、右側のいずれかにとることが一般的である。右側検定において、考えている統計量がある値よりも大きいという対立仮説のときには、左側に棄却域を設定し、棄却域に入らなかった右側の値を採用する。",
