    "question": "我が国における食品アクセスの確保に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA. 所得金額階層別世帯数の相対度数分布について平成9（1997）年と令和2年を比較すると、高所得世帯が増加している。また、食料の価格上昇による家計負担の増加額が収入に占める割合をみると、令和5年1月時点では高所得者層ほど負担が増加している。\nB. 生産・流通・消費等の過程で発生する未利用食品を、福祉施設や生活困窮者などに無償で提供するフードバンクの役割が大きくなっている。フードバンクにおける広域連携等の食品の受入・提供能力の強化に向けた先進的な取組の支援が行われるとともに、賞味期限内食品のフードバンクへの寄付が進むよう官民協働でネットワークを形成する取組が推進されている。\nC. フードバンク活動には活動費や人員不足といった運営上の課題があり、その多くが地方自治体によって運営されている。また、フードバンク活動では、生活困窮者への支援の観点から、未利用食品を無償で提供するだけではなく住宅や雇用の支援が総合的に行われている。\nD. 我が国では、過疎地域のみならず都市部においても食料品の購入や飲食に不便や苦労を感じる人が増えており、多くの市区町村が食品アクセス問題への対策が必要と認識している。その背景としては、住民の高齢化や地元小売業の廃業などが挙げられている。",
