    "question": "食料及び農業をめぐる国際情勢に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。なお、データは「令和5年版 食料・農業・農村白書」による。\n\nA. SDGs（Sustainable Development Goals）とは、2015年の国連サミットにおいて採択された、2030年を期限とする国際社会全体の開発目標である。これには、飢餓や貧困の撲滅、経済成長と雇用、気候変動対策等包括的な17の目標が設定されており、法的な拘束力はなく、各国の状況に応じた自主的な対応が求められる。\nB. FAO（国際連合食糧農業機関）をはじめとする国際機関が2022年に公表した報告書によると、2021年には、全世界で約7～8千万人が飢餓の影響下にあると推計されている。また、飢餓に直面する人々の地域別の数では、アフリカが最も多く、次いでラテンアメリカ・カリブ地域、アジアの順となっている。\nC. 2022年に生物多様性条約第15回締約国会議（COP15）第二部及び関連会合が開催され、2030年までの新たな世界目標である「昆明・モントリオール生物多様性枠組」等が採択された。この中で、農林水産関連では、陸と海のそれぞれ30％以上の保護・保全（30 by 30目標）、環境中に流出する過剰な栄養素や化学物質等による汚染リスクの削減等の目標が盛り込まれた。\nD. 食料需要の拡大、地球環境の破壊等のマクロ環境が変化する中、国内外の投資家や金融機関は、企業におけるESGの要素を投融資の判断に組み込む動きを拡大している。ESGとは、2006年にWTO（世界貿易機関）一般理事会で採択された、Environment（環境）、Social（社会）、Growth（成長）を考慮した投資活動や経営・事業活動のことを指す概念である。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "イ",
    "officialAnswerNumber": 2,
    "explanation": "SDGsは2015年に採択された2030年までの17目標である。2022年に採択された生物多様性の枠組には30 by 30や汚染リスク削減が盛り込まれた。",
    "choiceExplanations": {
      "ア": "AのSDGsに関する説明は妥当だが、Bの2021年の飢餓人口は世界で7～8億人規模であり、アジアが最も多かった。",
      "イ": "SDGsは2015年に採択された2030年までの17目標である。2022年に採択された生物多様性の枠組には30 by 30や汚染リスク削減が盛り込まれた。",
      "ウ": "Cの生物多様性枠組の説明は妥当である。Bの世界推計は約7～8億人で、地域別の人数が最大なのはアジアだった。",
      "エ": "Bの飢餓人口の規模と地域順が違う。DのGはGovernanceを表し、2006年には国連の支援で責任投資原則が発足した。",
      "オ": "Cは妥当だが、ESGのGは成長ではなくガバナンスを意味する。投資判断にESGを取り入れる責任投資原則の発足に関わったのは国連である。"
    },
