    "question": "糖料作物に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. テンサイはアブラナ科ダイコン属の2年生植物で、根部にショ糖を蓄積し甜菜糖の原料となる。甜菜糖は、我が国では北海道で生産され、砂糖の国内生産量のうち約40％を占める。製造される甜菜糖は分蜜糖であり、抽出後の残渣はビートパルプと呼ばれ、家畜の飼料として利用される。\nB. サトウキビはイネ科サトウキビ属の多年生植物で、多汁質の節間内部にショ糖が蓄積され、甘蔗糖の原料となる。我が国では主に沖縄県、鹿児島県で生産され、製造される甘蔗糖には分蜜糖と含蜜糖がある。搾汁後の残渣はバガスと呼ばれ、製糖工場の燃料や製紙用パルプの原料となる。\nC. テンサイの栽培法には直播栽培と移植栽培があり、雪解けが遅い北海道では移植栽培が行われてきたが、生産コスト低減等のため直播栽培が見直されている。連作すると収量や糖分含量が低下するほか、根腐病などの病害の発生が多くなるため、4年以上の輪作を行うことが望ましい。\nD. サトウキビの栽培法には、地上部の茎を土壌に挿して増殖させる新植栽培と、刈り取った株をそのまま残して再生茎を養成する株出し栽培がある。新植栽培には春植えと夏植えがあり、一般に生育期間の違いから夏植えは春植えより収量が高い。",
