    "difficulty": 3,
    "question": "次は、野菜の作型に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\nニンジンの主な作型には、春播き栽培、夏播き栽培、秋～冬播き栽培がある。［A］栽培は、冷涼な気候を好むニンジンの生態的特性からみて最も栽培に適した作型である。\nゴボウの主な作型には、春播き栽培、秋播き栽培がある。基本作型は［B］栽培であり、8～12月に収穫する。\nタマネギの主な作型には、春播き栽培、秋播き栽培、冬・春どり栽培がある。一般に［C］栽培では長日性の晩生系品種が用いられる。\nキュウリは作型が発達しており、普通栽培、早熟栽培、促成栽培、半促成栽培、抑制栽培などに分かれている。一般に［D］栽培とは、秋から冬にかけての栽培で普通栽培より収穫時期が遅い作型である。\nトマトの代表的な作型は、露地栽培、早熟栽培、促成栽培、半促成栽培、抑制栽培、夏秋雨よけ栽培である。生育前半のみを保温加温した［E］栽培では、栽培条件が良いので高品質多収量となる。",
