    "question": "花きの栽培上の特性に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. カーネーションは、キク科の植物であり、現在の園芸品種は四季咲きに改良されているが、本来は短日条件で開花が促進される量的短日植物である。また、我が国には令和3年度現在、米国や韓国などから、多くの切り花が輸入されている。\nB. バラは、バラ科の植物であり、ハイブリッドティー系、フロリバンダ系など、多様な品種が栽培されている。栽培技術の面では、通常の土壌栽培に加え、ロックウール耕が普及しており、アーチング方式やハイラック方式などの仕立て方法が開発されている。\nC. トルコギキョウは、北米が原産のリンドウ科の植物である。花色は、紫、桃、白などの単色のほか、覆輪、絞りなど豊富であり、花形は一重種、八重種などがある。また、苗は高温によりロゼット化するが、低温処理によりロゼット化を打破することができる。\nD. シクラメンは、地中海沿岸が原産のトウダイグサ科の植物である。栽培する上では、冷涼な気候を好むため、夏季は遮光を行い、光を弱めるとともに温度を下げることが重要である。また、開花調整には、植物成長調節剤であるオーキシンを散布することが効果的である。",
