    "difficulty": 3,
    "question": "他殖性植物の育種法に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 他殖性植物はヘテロ接合性が高く、数世代の自殖と選抜を行うと、ホモ接合が進んで特性はそろうが近交弱勢が生じるため、古くから集団育種法が用いられてきた。近年では、二つの自殖系統間で現れるアポミクシスを利用した育種も行われており、生産力や斉一性に優れた品種が開発されている。\nB. 集団選抜法は、栽培地の環境に適応した在来品種や系統を混合した複数の集団を作り、育種目標に合った形質を持つ集団を選抜して交雑し、次世代集団を作ることを繰り返す方法である。収量や成分含有量のように生育条件によって変動しやすい形質を選抜するため、組合せ能力検定を利用した集団選抜法が用いられることもある。\nC. 一代雑種育種法は、雑種強勢を利用してF₁雑種を品種にする育種法であり、F₁での雑種強勢の程度が大きな親系統の組合せを特定することや、F₁種子を効率的に生産する技術が必要である。トウモロコシのような子実の生産を行う植物では、F₁種子を効率よく生産し、かつ可稔とするため、細胞質雄性不稔系統、維持系統、稔性回復系統による三系法が用いられる。\nD. 合成品種育種法は、組合せ能力が高い複数の系統間で相互交雑を行い、その後代を品種として利用するものである。集団の均一性が高く、放任受粉による集団として利用できることから、種子を大量に増殖して使用でき、育種と採種のコストが軽減される。野菜や花の育種に用いられることが多い。",
