      "オ": "RNA干渉（RNAi）は、RNAに働きかけて内在性遺伝子の発現を増大させる技術であり、遺伝子機能の順遺伝学的解析に利用されている。ターゲット遺伝子と相補的な二本鎖RNAを細胞に導入すると、遺伝子から転写されたRNAが保護され、RNaseによる分解を受けずに蓄積するシステムを利用している。"
