    "question": "昆虫の利用に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. セイヨウオオマルハナバチは1990年代に我が国に導入され、主に施設栽培トマトの受粉に利用されている。これにより、それまでホルモン剤を用いてトマトを結実させていた労力が軽減された。その後、本種は特定外来生物に指定されたため、在来種のクロマルハナバチなどの利用が進んでいる。\nB. カイコが繭を作るために吐く糸は主にフィブロインとセリシンからできており、これらの絹タンパク質について衣料分野以外での用途開発が試みられている。また、カイコに感染するカイコ核多角体病ウイルスによるタンパク質生産がインターフェロンの製造などに応用されている。\nC. ミツバチの主な生産物としては、蜂蜜、ローヤルゼリー、プロポリス、蜜蠟などがある。2021年における我が国の蜂蜜の生産量も輸入量も共におよそ2,700トンであり、主な輸入元は米国である。ローヤルゼリーとプロポリスはミツバチ体内で合成されるが、蜜蠟は主に植物由来である。\nD. 種々の昆虫生産物が食品や飲料に利用・応用されている。コチニールカイガラムシが生産する樹脂は食品コーティング剤として利用されている。また、スズメバチの成虫が幼虫に与える唾液成分が疲労軽減に寄与しているとして、この成分を模倣したスポーツドリンクが開発されている。",
