      "ウ": "被覆によって養分の溶出期間や時期を制御できる。リニア型は施肥直後から溶出し、シグモイド型は一定の溶出抑制期間を経てから溶出する。",
      "エ": "原料を主に輸入に頼る点は合うが、輸入先の組合せが違う。例えばモロッコはリン酸アンモニウム、カナダは塩化カリウムの調達先である。",
