    "difficulty": 3,
    "question": "GDPやインフレ率などのマクロ経済変数は、経時的に観測された時系列データとして取り扱われることが多い。ある経済変数{yₜ}が、1階の自己回帰（AR(1)）過程に従って生成されるとする。\n\nyₜ = β₀ + β₁yₜ₋₁ + εₜ，t = 1，…，T.\n\nただし、tは時間を表すインデックス、εₜは独立かつ同一の分布に従う誤差項である。また、y₀ = 0とし、特に断りのない限りパラメータβ₀、β₁は有限である。\n{yₜ}の平均、分散、自己共分散が有限で、時間を通じて一定であるとき、弱定常性（以下では単に「定常性」という。）の条件を満たすという。\n上記のAR(1)過程について、以下の記述のア、イ、ウに当てはまるものの組合せとして最も妥当なのはどれか。\n{yₜ}が定常性の条件を満たさないのは、［ア］のときである。上記のAR(1)過程がランダムウォークと呼ばれるのは、パラメータ［イ］の値が［ウ］の場合である。",
