    "question": "我が国の農産物及び食品の流通や取引に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 食品流通における生鮮食品の特徴として、第一に貯蔵性に乏しいこと、第二に大きさ・色・品質といった製品の規格化が容易であること、第三に品質や包装などにより製品差別化が容易であることが挙げられる。\nB. 卸売市場の主要な機能は、第一に集荷（品揃え）・分荷機能、第二に価格形成機能、第三に代金決済機能、第四に情報受発信機能である。卸売市場には、都道府県知事が認可する中央卸売市場と、市町村長が認可する地方卸売市場がある。卸売市場での取引は、せり取引のみ認められており、相対取引は禁止されている。\nC. コールドチェーン（低温流通機構）とは、食品の品質を保持するために、生産、流通、消費の過程で、低温の連続性が途切れないようにする流通の仕組みのことである。具体的な取組の例としては、産地での予冷、流通の場面での低温輸送車の利用、小売店店頭での冷蔵ショーケースの利用などがある。\nD. 令和4年度における鶏卵の小売価格は、上昇傾向で推移した。これは、飼料価格の高騰等による生産コストの上昇に加え、高病原性鳥インフルエンザの影響によって生産減少が生じたためである。これにより、消費者向けの鶏卵では、地域によっては購入制限を設ける事例や、夕方には品薄になるといった事例があった。",
