    "difficulty": 3,
    "question": "短期の完全競争市場において、ある企業の農産物の平均可変費用曲線AVCが次式で表されるものとする。このとき、固定費用が12、農産物の価格が48であるとする。企業が利潤最大化を行った際に得られる利潤として最も妥当なのはどれか。\n\nAVC = x² − 6x + 12（x：生産量）",
