    "question": "我が国の農業関連団体及び制度に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 農業協同組合（以下「農協」という。）は、農業者等の組合員により自主的に設立される相互扶助組織である。平成29年度から令和3年度の5年間で、総合農協＊の准組合員数は増加傾向、正組合員数は減少傾向にある。組合数は、総合農協の合併が進んでいることにより、減少傾向にある。\nB. 農業委員会は、都道府県に設置されている行政委員会である。農業委員会では、農地の権利移動の許可・不許可の決定などのほか、農業者の所得向上に向け、農産物の販売や生産資材の供給を行っている。\nC. 農業共済制度は、農業共済組合及び農業共済事業を実施する市町村、都道府県単位の農業共済組合連合会、国の3段階で運営されてきたが、近年2段階で運営できるよう1県1組合化が推進されている。本制度の目的は農協の共済事業と異なり、農業者の経営安定を図るため自然災害による収穫量の減少等の損失を補塡することである。\nD. 土地改良区は、土地改良事業を行政に代わって実施する農業者の組織であり、農業者の発意により市町村長の認可によって設立されるものである。ただし、土地改良事業によって利益を受ける地区内の農業者であっても、加入は任意となっている。\n\n＊ 信用、共済、販売等の事業を総合的に行う農協のこと。",
