    "question": "我が国の農林水産物・食品の輸出に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。なお、データは「令和4年版 食料・農業・農村白書」及び「令和5年版 食料・農業・農村白書」による。\n\nA. 我が国の農林水産物・食品の輸出額は2021年に初めて1兆円を超え、今後は2025年までに2兆円、2030年までに5兆円を目標としている。その達成に向け、政府は2020年に策定した「農林水産物・食品の輸出拡大実行戦略」を改訂し、更なる輸出拡大に取り組んでいる。\nB. 2022年の我が国の農林水産物・食品の輸出額を国・地域別にみると、第一位は米国、第二位は韓国となっている。輸出額の多いフランス、イタリアと比較して我が国の農林水産物・食品の生産額に占める輸出額の割合は15％と低い分、輸出増のポテンシャルは高い。\nC. 東京電力福島第一原子力発電所の事故に伴い、55か国・地域において、日本産農林水産物・食品の輸入停止や放射性物質の検査証明書等の要求、検査の強化といった輸入規制措置が講じられた。政府一体となって働きかけを行ってきた結果、2022年度においては、輸入規制措置が英国（北アイルランドを除く）、インドネシアで撤廃された。\nD. 我が国の茶の輸出額は、海外のコーヒーブームや他国産の茶に競争で負けていることから、近年減少傾向にある。ただ、有機栽培による茶は海外でのニーズも高く、我が国からの有機同等性の仕組みを利用した輸出量は増加傾向にあり、2021年は前年に比べ約3割増加し、過去最高となった。輸出先国・地域としては、特にEUや台湾が大きな割合を占めている。",
