    "difficulty": 3,
    "question": "［　］内に当てはまる近交係数の値として最も妥当なのはどれか。\n\n血統が明らかなとき、近交係数は、ある個体の対立遺伝子が共に共通祖先の同一遺伝子に由来する確率として計算される。個体Zの両親をX、Y、両親の共通祖先をPとすると、個体Zの近交係数F_Zは、\n\nF_Z = Σ{(1／2)^(n_X + n_Y + 1)(1 + F_P)}\n\nで表される。ここで、n_X及びn_YはそれぞれZの両親X、Yから共通祖先Pまでの世代数で、F_PはPの近交係数であり、Σは両親X、Yから共通祖先までの全ての経路を足し合わせることを意味する。\n下に示された家畜の血統図において、個体A、B、Cの近交係数が全て0のとき、個体Zの近交係数は小数点第3位を四捨五入すると［　］となる。",
