      "イ": "共通祖先Aの経路のうち、YからAへ直接つながる場合には、X側のB経由とC経由の二通りをそれぞれ加える。Cを経由してYがAにつながる場合も、X側がB経由であれば加える。",
      "ウ": "Cの1／8とAへの直接のY経路に対応する二つの1／16を足すと0.25になる。さらにX→B→AとY→C→Aの組の1／32を加える。",
      "エ": "Cは1／8を、Aは重複しない二つの世代数(2, 1)と一つの(2, 2)から1／16 + 1／16 + 1／32を寄与する。合計0.28125を四捨五入して0.28となる。",
