      "イ": "組換え価とは、全ての配偶子に占める組換え型の配偶子数の割合として算出される。同一染色体上にある二つの遺伝子座間での組換え価は、多重交叉の場合を除いて基本的には2遺伝子座間の物理的な距離に反比例する。組換え価1％は染色体地図上の1単位として定義され、1モルガンという。",
