    "difficulty": 3,
    "question": "家畜の着床・胎盤形成・分娩に関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. ウシやブタでは、インターフェロンτが妊娠認識物質として栄養膜細胞から分泌される。インターフェロンτは子宮内膜からのPGF₂αサージを抑制することで、黄体機能が維持される。\nB. 絨毛膜が子宮内膜と接着又は結合している部分を胎盤と呼ぶ。ウシの胎盤では子宮内膜の全体に絨毛膜が接着する。その際、絨毛膜の一部は、子宮内膜上皮細胞に遊離し、上皮細胞と融合することで二核細胞となる。\nC. ウシでは、胎子下垂体から副腎皮質刺激ホルモンの分泌量が増加し、胎子副腎からのコルチゾール分泌が促されることで分娩が発来する。その際、母体血中におけるプロジェステロンの低下及びエストロジェンの上昇により子宮平滑筋が収縮する。\nD. ウシの分娩は、子宮頸管の開口から産道形成までの開口期、胎子娩出までの娩出期、胎子胎盤が娩出されるまでの後産期に分けられる。また、分娩開始の徴候には、外陰部の腫大、乳房の肥大、直腸温の低下などがある。",
