    "difficulty": 3,
    "question": "次は、哺乳動物の受精と初期胚発生に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。\n\n射出された精子は、受精部位である［A］に移動し、卵子と受精することで受精卵となる。胚ゲノムの活性化までは卵子に蓄えられた母性因子によって発生が制御されている。ウシ、ヒツジでは［B］細胞期に大規模な胚ゲノムの活性化が起こる。その後、ウシでは、［C］細胞期になったころから、割球間の結合が強まって割球個々の境が不明瞭となる。これをコンパクションと呼び、［D］依存性の細胞接着因子であるE-カドヘリンが関与する。その後、胚の内部に胞胚腔が形成され胚盤胞へと発生する。胚盤胞形成の過程では、［E］へと分化する栄養外胚葉、胎子へと分化する内部細胞塊と呼ばれる2種類の細胞群に分かれる。",
