    "question": "家畜の成長や代謝に係るホルモンに関する記述A～Dのうち、妥当なもののみを全て挙げているのはどれか。\n\nA. 上皮小体から分泌されるパラソルモンは、ポリペプチドホルモンであり、腎臓でのカリウムの再吸収促進及びリン酸排出促進作用を持つ。また、パラソルモンにより生成が促進されるビタミンKによって、腸管でのカリウム吸収が促進される。\nB. グルカゴンは、ペプチドホルモンであり、膵臓より分泌され、肝臓に作用する。肝臓では、cAMPを増加させることによってホスホリラーゼ活性を増し、グリコーゲン合成を減少させ、分解を増加させる。また、アミノ酸からの糖新生を促進し、血糖値を上昇させる。\nC. サイロキシンは、四つのヨウ素分子を分子内に有する甲状腺ホルモンの一種である。主要な作用は、細胞の酸素消費を増加させ、基礎代謝を亢進することにより、熱産生を増加させることである。\nD. グルココルチコイドは、ステロイドホルモンであり、副腎皮質より分泌される。膵臓でのグリコーゲン分解を促進し、糖新生を抑制する。また、タンパク質分解を促進し、生じたアミノ酸は脱アミノ作用を受けてグルコースの前駆体となる。",
