    "choices": {
      "ア": "家畜において温熱環境を決定する要素は、温度、湿度、風、気圧の四つであり、温度は温熱環境を決定する最も基本的な要素である。ほかの三つは温度と関連して家畜の体温調節に大きな影響を与える要素であり、暑熱環境では放熱を阻害して体温を上昇させる。",
      "イ": "産熱は、筋肉の運動による発熱や消化・吸収・泌乳などの家畜の生理的活動により発現する。寒冷環境では、ふるえにより産熱量が低下し、非ふるえ産熱により産熱量が増大する。反すう家畜における第一胃内発酵に伴う発酵熱は産熱の要素とならない。",
      "ウ": "放熱は、家畜の体表面と環境の温度差により熱の移動が起こる潜熱放散と、家畜体からの水の蒸発による顕熱放散がある。家畜の汗腺はヒトに比べて発汗機能が強く、加えて発汗によらずに皮膚下層から体表面に移動した水分の蒸発や熱性多呼吸により放熱を増加させている。",
      "エ": "家畜がエネルギー消費を伴う体温調節反応を必要としない環境温度の範囲を熱的中性圏といい、その下限を下臨界温度、上限を上臨界温度という。熱的中性圏の範囲は家畜の種類や発育ステージによって異なり、被毛の長さなど家畜の状態によっても変化する。",
      "オ": "暑熱環境では、摂食量の減少によって摂取代謝エネルギーが減少し、産熱量が減少する。寒冷環境では、摂食量の減少によって摂取代謝エネルギーが減少し、体温維持のために産熱量が増加する。"
    },
