    "question": "次は、我が国の水産物の輸出に関する記述であるが、A～Eに当てはまるものの組合せとして最も妥当なのはどれか。なお、データは「令和5年版 水産白書」による。\n\n我が国の水産物輸出額は、2012年以降はおおむね増加傾向で推移してきており、2022年は約4,000億円となった。同年における輸出額が多い輸出先国・地域の上位3位は中国、香港、［A］で、これら3か国・地域で5割以上を占めている。\n農林水産省は、農林水産物・食品の輸出拡大を図るため、「食料・農業・農村基本計画」において、2030年までの農林水産物・食品の輸出額の目標を設定しており、この目標の中で水産物の輸出額は［B］とされている。また、「農林水産物・食品の輸出拡大実行戦略」では、我が国の強みを有する品目を輸出重点品目に選定し、品目毎に輸出拡大を重点的に目指す主なターゲット国・地域や輸出目標を設定しており、この品目のうち水産物としては、ぶり、たい、ホタテガイ、真珠及び［C］が選定されている。\n東日本大震災に伴って起きた東京電力福島第一原子力発電所の事故の後、我が国の水産物の安全性を確保するため、国、関係都道県、漁業関係団体が連携して放射性物質モニタリングを行っている。［D］以外の放射性物質を、環境放出の際の規制基準を満たすまで浄化した水であるALPS処理水の海洋放出に当たっては、［E］と協力して安全性の確保を図っていくこととしている。",
