    "question": "次は、1995年に国連食糧農業機関（FAO）で採択された「責任ある漁業のための行動規範」の一部を抜粋したものであるが、ア～エに当てはまるものの組合せとして最も妥当なのはどれか。なお、［伏字］は設問の都合上伏せてある。\n\nThe widespread introduction in the mid-seventies of exclusive economic zones (EEZs) and the adoption in 1982, after long deliberations, of the ［ア］ provided a new framework for the better management of marine resources. The new legal regime of the ocean gave coastal States rights and responsibilities for the management and use of fishery resources ［イ］ which embrace some 90 percent of the world's marine fisheries. Such extended national jurisdiction was a necessary but insufficient step toward the efficient management and sustainable development of fisheries. Many coastal States continued to face serious challenges as, lacking, experience and financial and physical resources, they sought to extract greater benefits from the fisheries ［イ］.\n\nIn recent years, world fisheries have become a market-driven, dynamically developing sector of the food industry and coastal States have striven to take advantage of their new opportunities by investing in modern fishing fleets and processing factories in response to growing international demand for fish and fishery products. By the late 1980s it became clear, however, that fisheries resources could no longer sustain such rapid and often uncontrolled exploitation and development, and that new approaches to fisheries management embracing ［ウ］ and environmental considerations were urgently needed. The situation was aggravated by the realization that unregulated fisheries ［伏字］, in some cases involving ［エ］ and highly migratory fish species, which occur within and outside EEZs, were becoming a matter of increasing concern.",
