    "question": "次は、漁具の選択性に関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n生物の大きさによって漁獲される確率が異なることをサイズ選択性といい、体長に対する曲線や関数で表現される。例えば、袋網における網目選択性では、対象生物が網目に比べて十分小さなときは全て網目を抜け出るものの、大きくなるにつれて網目に保持されるようになるため、その曲線は以下の図のようにS字型になる。\n\nS字型曲線の特性を表す指標として、50％選択体長（l₅₀）と、例えば75％選択体長（l₇₅）と25％選択体長（l₂₅）の差で表される［A］がある。選択率が50％である50％選択体長は、漁具から逃避される確率と漁獲される確率が等しくなる体長であり、資源管理における［B］に用いられる。\nS字型曲線の簡易的な表現として次のロジスティック式がよく用いられる。\n\nr(l) = {exp(a + bl)／[1 + exp(a + bl)]} × 100　(0 < r(l) < 100)\n\nただし、r(l)は選択率（％）、lは体長、aとbはパラメータである。このパラメータによって50％選択体長は［C］、［A］は［D］と表すことができる。",
    "choices": {
      "ア": "ナイフエッジ ／ 成熟体長 ／ −(a + 0.5)／(2b) ／ logₑ 2／b",
      "イ": "ナイフエッジ ／ 成熟体長 ／ −a／b ／ 2 logₑ 3／b",
      "ウ": "ナイフエッジ ／ 漁獲開始体長 ／ −a／b ／ 2 logₑ 3／b",
      "エ": "選択レンジ ／ 漁獲開始体長 ／ −(a + 0.5)／(2b) ／ logₑ 2／b",
      "オ": "選択レンジ ／ 漁獲開始体長 ／ −a／b ／ 2 logₑ 3／b"
    },
    "answer": "オ",
    "officialAnswerNumber": 5,
    "explanation": "選択レンジはl₇₅とl₂₅の差で、50％選択体長は漁獲開始体長に用いる。ロジスティック式からそれぞれl₅₀ = −a／b、l₇₅ − l₂₅ = 2 ln 3／bとなる。",
    "choiceExplanations": {
      "ア": "25％と75％に対応する体長差は選択レンジである。50％のとき指数部分のa + blは0となり、体長は−a／bである。",
      "イ": "式の値は合うが、体長差の名称は選択レンジである。50％選択体長は漁獲開始体長の指標であり、成熟の指標とは区別する。",
      "ウ": "漁獲開始体長と二つの式は合っている。l₇₅とl₂₅の差で示す変化の幅は、選択レンジと呼ぶ。",
      "エ": "名称と使用目的は合う。50％ではa + bl = 0、75％と25％ではそれぞれln 3と−ln 3なので、選択レンジは2 ln 3／bである。",
      "オ": "選択レンジはl₇₅とl₂₅の差で、50％選択体長は漁獲開始体長に用いる。ロジスティック式からそれぞれl₅₀ = −a／b、l₇₅ − l₂₅ = 2 ln 3／bとなる。"
    },
