    "question": "養殖用配合飼料に関する記述A～Dのうち、妥当なもののみを挙げているのはどれか。\n\nA. 配合飼料における炭水化物の主な役割は、エネルギー源の供給と粘結剤としての効果である。デンプンは安価な上にブリなどの海産養殖魚種で消化利用性が高いため、ブリ用飼料には主要なエネルギー源として30％程度添加されている。\nB. 配合飼料における脂質の主な役割は、エネルギー源と必須脂肪酸の供給である。一般に、淡水魚は高度不飽和脂肪酸を合成する能力が低いため、アラキドン酸を必須脂肪酸として要求するが、海産魚はリノール酸から高度不飽和脂肪酸を合成する能力が高いため、リノール酸を必須脂肪酸として要求する。\nC. 魚類の必須アミノ酸には、リシン（リジン）やメチオニンなどがある。そのほかに、海産魚に必要な栄養素として、アミノ酸に似た物質であるタウリンが知られている。飼料原料の中で魚粉は必須アミノ酸をバランスよく含むが、大豆油かすやコーングルテンミールは一部の必須アミノ酸が不足している。\nD. エクストルーデッドペレットは、高温高圧下で製造された固形ペレットで、ブリなどの養殖に広く使われている。エクストルーデッドペレットは多孔質で浮力を調節できるため沈降タイプに加えて浮遊タイプも製造できるという利点があるが、ドライペレットより製造コストが高いという欠点もある。",
    "choices": {
      "ア": "A、B",
      "イ": "A、C",
      "ウ": "B、C",
      "エ": "B、D",
      "オ": "C、D"
    },
    "answer": "オ",
    "officialAnswerNumber": 5,
    "explanation": "魚粉は必須アミノ酸を比較的バランス良く含み、一部の植物性原料では不足するアミノ酸を補う必要がある。エクストルーデッドペレットは浮力を調整できるが製造コストが高い。",
    "choiceExplanations": {
      "ア": "ブリなどの肉食性の魚ではデンプンを大量に利用できない。長鎖の高度不飽和脂肪酸の合成能力も、多くの海産魚で限られている。",
      "イ": "Cは妥当である。Aはブリのデンプン利用性を高いとし、飼料中の主なエネルギー源にしている点が妥当でない。",
      "ウ": "Cは妥当だが、Bでは多くの海産魚が長鎖の高度不飽和脂肪酸を十分に合成できるとしている。実際には飼料からの供給が重要である。",
      "エ": "Dのペレットの性質は妥当である。Bの海産魚と淡水魚の脂肪酸の合成能力の傾向は逆である。",
      "オ": "魚粉は必須アミノ酸を比較的バランス良く含み、一部の植物性原料では不足するアミノ酸を補う必要がある。エクストルーデッドペレットは浮力を調整できるが製造コストが高い。"
    },
