      "ウ": "Aは二枚貝や二次汚染に関連するノロウイルスで、BとCはそれぞれ神経症状を起こすボツリヌス菌と生魚介類に関連する腸炎ビブリオである。Dはアニサキス、Eはヒラメのクドアである。",
