      "イ": "オミッションテストは、合成エキスから特定の成分を除いたときの味の変化を調べる。完全な組成のエキスと比較することで、除いた成分の呈味への寄与を評価できる。",
      "ウ": "エキス成分には糖や有機酸といった低分子の無窒素成分も含まれる。タウロピンをイミダゾールジペプチドに含める説明も誤っている。",
      "エ": "Dのオミッションテストの説明は妥当である。Aはタンパク質などを含め、糖や有機酸を除外する点に誤りがある。",
