    "question": "次は、水産エコラベルに関する記述であるが、A～Dに当てはまるものの組合せとして最も妥当なのはどれか。\n\n水産エコラベルとは、水産資源の持続性や環境に配慮した方法で生産された水産物に対して、消費者が選択的に購入できるよう商品にラベルを表示する仕組みである。水産エコラベルは、国内では、一般社団法人マリン・エコラベル・ジャパン協議会による漁業と養殖業を対象としたMEL、英国に本部を置く海洋管理協議会による漁業を対象とした［A］、オランダに本部を置く水産養殖管理協議会による養殖業を対象とした［B］などの水産エコラベル認証が主に活用されている。水産エコラベルは、［C］の水産委員会が採択した水産エコラベルガイドラインに沿った取組に対する認証を指すものとされている。しかし、世界には審査基準の異なる様々な水産エコラベルがあるため、水産エコラベルの信頼性確保と普及改善を目的に、［D］から承認を受けることが、国際的な水産エコラベル認証スキームとして通用するための潮流となっている。",
