    "difficulty": 3,
    "question": "次は、旅行者が海産物による食中毒を避けるための注意事項を説明した記述であるが、ア～エに当てはまるものの組合せとして最も妥当なのはどれか。なお、■は設問の都合上伏せてある。\n\nCiguatera toxins do not affect the texture, taste, or smell of fish, nor are they destroyed by canning, cooking, freezing, pickling, salting, or smoking, or by gastric acid. To prevent ciguatera fish poisoning, travelers should avoid or limit consumption of ［ア］ fish, particularly fish that weigh >5 pounds: counsel travelers to never eat high-risk fish (e.g., barracuda, moray eel) and to avoid eating the parts of the fish (e.g., the head, intestines, liver, roe) that concentrate ciguatera toxin.\n\n（中略）\n\nShellfish, including crustaceans (Dungeness crab, lobster, and shrimp), filter-feeding bivalve mollusks (clams, cockles, mussels, oysters, and scallops), and gastropod mollusks (abalone, moon snails, and whelks) can harbor toxins that result in several different poisoning syndromes. Toxins originate in small marine organisms (■ or ［イ］) ingested and concentrated by shellfish.\n\n（中略）\n\nShellfish poisoning can be prevented by avoiding potentially contaminated shellfish, which is particularly important in areas during or shortly after algal ［ウ］, locally referred to as “red tides” or “brown tides.” Consuming shellfish also carries a very high risk for infection from various viral and bacterial ［エ］. Ideally, travelers to developing countries should consider avoiding eating shellfish. Marine shellfish toxins cannot be destroyed by cooking or freezing.",
